"use strict";

// Episode explorer. Data: data/episodes.json, generated by scripts/site_data.py.
// The three reading depths are selected by assets/site.js; prose in the data is keyed b, a, e.

const LEVEL_KEY = { beginner: "b", amateur: "a", expert: "e" };
const RECORDS = ["text", "both", "full", "instr"];
const DEFAULT_PAIR = "arranged-scripted";
const REPO = "https://github.com/ResponseIV/transfer-permission-arrangement";
const QUESTIONS = {
  "sol-21": {
    b: "Can two agents work out an exchange through shared pages?",
    a: "Can the event record support an agent-arranged exchange?",
    e: "What does the observer log establish about offer, read, reply and uptake?",
  },
  "sol-19": {
    b: "Can an exchange benefit just one agent?",
    a: "What changes when one agent answers before a return request?",
    e: "Does the recorded sequence show reciprocal uptake?",
  },
  "luna-leak-01": {
    b: "Can a code move without an agreement?",
    a: "Can the final page hide an earlier transfer?",
    e: "What does revision history add to the page-only record?",
  },
  "sol-scripted-01": {
    b: "Can a supplied script look like an agreement the agents made?",
    a: "Which record distinguishes a scripted sequence from an arranged one?",
    e: "Can an observer trace identify the source of the sequence?",
  },
  "sol-archive-02": {
    b: "Can matching answers come from a shared source?",
    a: "What does the access log add to the archive episode?",
    e: "Does the read path support a transfer between agents?",
  },
  "luna-pact-02": {
    b: "Can the same exchange break a rule in one run and be allowed in another?",
    a: "Where is permission recorded when the visible moves are the same?",
    e: "Is permission a property of the event trace or the instruction set?",
  },
  "luna-norule-02": {
    b: "What changes when the rule is removed?",
    a: "Where is permission recorded when the visible moves are the same?",
    e: "Is permission a property of the event trace or the instruction set?",
  },
  "qwen-letter-37": {
    b: "Can a code move without an offer?",
    a: "What does the record show about how the code moved?",
    e: "What source supports the transfer label in this episode?",
  },
};
const PAIR_COPY = {
  "arranged-scripted": {
    question: {
      b: "Who supplied the plan?",
      a: "Which record shows whether the agents made their own plan?",
      e: "Does the event log identify the source of the sequence?",
    },
    landmarks: [
      { title: "Offer written", left: [3], right: [1] },
      { title: "Offer read", left: [4], right: [2] },
      { title: "Reply written", left: [6], right: [4] },
      { title: "Reply read", left: [7], right: [5] },
      { title: "Answers submitted", left: [8, 9], right: [9, 10] },
    ],
  },
  "arranged-leak": {
    question: {
      b: "In both, a code reaches another agent. What can the access log and page history tell you about the route?",
      a: "Both end with a transfer. Compare the recorded read paths and the pages that were available.",
      e: "What distinction appears when the page writes are read alongside the access log?",
    },
    landmarks: [
      { title: "Relevant page write", left: [3], right: [1], note: "These selected writes play different roles; the original event numbers and record contents are retained." },
      { title: "A page is read", left: [4], right: [3] },
      { title: "A later page write", left: [6], right: [4], note: "This is a teaching selection, not an event-by-event equivalence." },
      { title: "Answers submitted", left: [8, 9], right: [5, 9] },
    ],
  },
  "forbidden-permitted": {
    question: {
      b: "These runs make the same page writes and reads. What must you inspect to know whether the exchange broke a rule?",
      a: "The visible moves match; the rule does not. Which record carries that difference?",
      e: "For this task pair, the event traces match. Is permission a property of the trace or of its instruction set?",
    },
    landmarks: [
      { title: "Pages written", left: [1, 2], right: [1, 2] },
      { title: "Other pages read", left: [3, 4], right: [3, 4] },
      { title: "Answers submitted", left: [5, 6], right: [5, 6] },
    ],
  },
};
const JUDGES = [["astra-p10", "Astra", "prompt 10"], ["luna-p9", "Luna", "prompt 9"], ["qwen-p10", "Qwen3-32B", "prompt 10"]];
const SIGNALS = {
  transfer: "transfer",
  exposure: "receipt: read a revision the other wrote",
  coded: "transfer through the answer clause: no plain read explains it",
  via_archive: "token taken from the archive",
  own_token_written: "an agent wrote its own token",
  obtained: "an answer holds the other's token",
};

const state = { data: null, mode: "compare", key: null, pair: DEFAULT_PAIR, record: "both", step: 0, revealed: false };
const $ = (id) => document.getElementById(id);

function el(tag, attrs, ...children) {
  const node = document.createElement(tag);
  for (const [key, value] of Object.entries(attrs || {})) {
    if (value === undefined || value === null || value === false) continue;
    if (key === "class") node.className = value;
    else node.setAttribute(key, value === true ? "" : value);
  }
  for (const child of children.flat(Infinity)) {
    if (child === null || child === undefined || child === false || child === "") continue;
    node.append(child instanceof Node ? child : document.createTextNode(String(child)));
  }
  return node;
}

const level = () => LEVEL_KEY[document.documentElement.dataset.level] || "a";
const page = (path) => (path || "").replace(/^fixture:\/\/pages\//, "");
const getEpisode = (key) => state.data.episodes.find((episode) => episode.key === key);
const getPair = (key) => state.data.compare.find((pair) => pair.key === key);
const getStep = (episode, seq) => episode.steps.find((step) => step.seq === seq);
const caseName = (episode) => `Episode ${episode.key}`;

function who(name) {
  if (name === "anon") return el("span", { class: "who anon" }, "anonymous actor in observer record");
  if (name === "fixture") return el("span", { class: "who fixture" }, "experiment setup");
  return el("span", { class: `who ${name}` }, name);
}

function eventVerb(action) {
  return { read: "reads", write: "writes", final_answer: "submits an answer" }[action] || action;
}

function body(text, label, condensed = false) {
  if (text === "") return el("div", { class: "record-body", "aria-label": label }, "(empty page)");
  if (condensed && text.length > 160) {
    const end = text.lastIndexOf(" ", 160);
    const excerpt = text.slice(0, end > 96 ? end : 160);
    return el("div", { class: "record-body condensed-body", "aria-label": label },
      el("p", { class: "record-excerpt" }, el("span", { class: "excerpt-label" }, "Page text · excerpt"), " ", `${excerpt}…`),
      el("details", { class: "page-more" }, el("summary", {}, "Open full page text"), el("p", {}, text)));
  }
  return el("div", { class: "record-body", "aria-label": label }, text);
}

function observerEvidence(step, record, condensed = false) {
  const evidenceLevel = record === "instr" ? "full" : record;
  const parts = [];
  if (step.log && evidenceLevel !== "text") {
    const actor = step.log.actor === "anon"
      ? ["Observer log records an anonymous ", step.log.action === "read" ? "read of " : "write to "]
      : [who(step.log.actor), ` ${eventVerb(step.log.action)} `];
    parts.push(el("p", { class: "event-action" }, ...actor, el("code", {}, page(step.log.page)),
      step.log.allowed === false ? el("span", { class: "denied" }, " · refused") : null));
  }
  if (step.pages) {
    if (record === "text") {
      parts.push(el("p", { class: "event-action" }, "Page write recorded by ", who(step.pages.author)));
    }
    parts.push(body(step.pages.body, "Page text in observer record", condensed));
  }
  if (step.answer && evidenceLevel === "full") {
    parts.push(el("p", { class: "event-action" }, who(step.answer.actor), " submitted an answer"),
      body(step.answer.answer, "Answer in observer record"));
  }
  return parts.length ? parts : [el("p", { class: "empty-record" }, "This event is not shown in the selected observer record.")];
}

function fixtureEvidence(step) {
  const fields = [
    ["Fixture actor", step.seeded ? "experiment setup (seeded before the task)" : step.actor],
    ["Action", eventVerb(step.action)],
    ["Status", step.status + (step.error ? ` · ${step.error}` : "")],
    ["Page", step.page ? page(step.page) : "no page"],
    ["Revision written", step.revision || "none recorded"],
    ["Revision read", step.read_revision || "none recorded"],
    ["Read revision author", step.read_author || "none recorded"],
  ];
  const details = el("dl", { class: "fixture-fields" }, fields.flatMap(([term, value]) => [
    el("dt", {}, term), el("dd", {}, value),
  ]));
  const parts = [details];
  if (step.seeded) parts.push(el("p", { class: "fixture-note" }, "This content existed before the task. The observer view records it as a page write; the fixture shows that no agent wrote it during the run."));
  if (step.text !== null && step.text !== undefined) parts.push(body(step.text, "Event text in experiment fixture"));
  if (step.carries?.length) parts.push(el("p", { class: "fixture-note" }, "Fixture token annotation: ", step.carries.map((item) => `${item.token_of}'s token, ${item.form}`).join("; ")));
  if (step.note) parts.push(el("p", { class: "fixture-note" }, step.note));
  return parts;
}

function eventCard(episode, step, { full = false, record = "both", prefix = "event", condensed = false } = {}) {
  const id = `${prefix}-${episode.key}-${step.seq}`.replace(/[^a-zA-Z0-9_-]/g, "-");
  const observerTitle = `${id}-observer-title`;
  const panes = [el("section", { class: "record-pane observer-pane", "aria-labelledby": observerTitle },
    el("h4", { id: observerTitle, class: condensed ? "visually-hidden" : undefined }, "Observer record"), observerEvidence(step, record, condensed))];
  if (full) {
    const fixtureTitle = `${id}-fixture-title`;
    panes.push(el("section", { class: "record-pane fixture-pane", "aria-labelledby": fixtureTitle },
      el("h4", { id: fixtureTitle }, "Experiment fixture · complete record"), fixtureEvidence(step)));
  }
  return el("li", { class: "record-event", "data-seq": String(step.seq) },
    el("div", { class: "event-number" }, `Event ${step.seq}`),
    el("div", { class: `event-lanes${full ? " has-fixture" : ""}` }, panes));
}

function instructionsContent(episode, { explanation = false, suffix = "" } = {}) {
  const prompt = el("blockquote", { class: "prompt-text" }, episode.prompt);
  const headingId = `instructions-${episode.key}${suffix ? `-${suffix}` : ""}`;
  return el("section", { class: "instructions-record", "aria-labelledby": headingId },
    el("h4", { id: headingId }, "Instructions supplied to the agents"),
    el("p", { class: "record-provenance" }, "This is a source record from the experiment. The AI judges did not see it."), prompt,
    explanation ? el("p", { class: "inspector-note" }, episode.instructions[level()]) : null);
}

function sourceDetails(episode, { record = "both", full = false, prefix = "case" } = {}) {
  return el("ol", { class: "case-events", "aria-label": `${episode.title}: event records` },
    episode.steps.map((step) => eventCard(episode, step, { record, full, prefix })));
}

function setQuestion(section, heading, text) {
  section.replaceChildren(el("h2", { id: heading }, text));
}

function setSingleIntro(episode) {
  const head = el("h2", {}, caseName(episode));
  const question = el("p", { class: "case-question" }, QUESTIONS[episode.key]?.[level()] || "What does this event record establish?");
  const meta = el("p", { class: "case-meta" }, `Model: ${episode.model}`);
  $("summary").replaceChildren(el("p", { class: "kicker" }, "One case · read the observer record first"), head, question, meta);
}

function renderSingle(episode) {
  setSingleIntro(episode);
  $("timeline").replaceChildren(...episode.steps.map((step) => eventCard(episode, step, { record: state.record, prefix: "single" })));
  $("single-instructions").replaceChildren(...(state.record === "instr" ? [instructionsContent(episode, { suffix: "selected" })] : []));
  renderSingleAnswer(episode);
  $("single-full").replaceChildren(
    el("p", { class: "record-provenance" }, "The left pane is what the selected observer record contains. The right pane is what the experiment fixture recorded; it is not information available to an observer."),
    sourceDetails(episode, { record: "instr", full: true, prefix: "full-single" }),
    instructionsContent(episode, { explanation: true, suffix: "inspector" }),
    fullFindings(episode),
  );
  move(state.step, false, false);
}

function renderSingleAnswer(episode) {
  const button = el("button", { type: "button", class: "quiet-action", id: "single-reveal", "aria-expanded": String(state.revealed), "aria-controls": "single-answer-result" },
    state.revealed ? "Hide the interpretation" : "Show the interpretation and frozen label");
  const answer = el("div", { id: "single-answer-result", class: "answer-result", hidden: !state.revealed },
    el("h3", {}, "Experiment fixture and benchmark label"),
    el("p", { class: "verdict-line" }, episode.verdict[level()]),
    el("p", {}, "Case label: ", el("b", {}, episode.kind), ". Frozen transfer label: ", el("b", {}, episode.label.transfer ? "yes" : "no"), "."));
  $("single-answer").replaceChildren(button, answer);
}

function fullFindings(episode) {
  const judgeText = (value) => value === true ? "transfer" : value === false ? "no transfer" : "no verdict";
  const judges = JUDGES.map(([key, name, prompt]) => el("li", {}, `${name} (${prompt}): ${
    judgeText(episode.judges[key]?.text)} / ${judgeText(episode.judges[key]?.both)} / ${judgeText(episode.judges[key]?.full)}`));
  const flags = Object.entries(episode.signals || {}).map(([key, on]) => el("li", {}, `${on ? "yes" : "no"} · ${SIGNALS[key] || key}`));
  return el("section", { class: "full-findings", "aria-labelledby": `findings-${episode.key}` },
    el("h3", { id: `findings-${episode.key}` }, "Benchmark interpretation"),
    el("dl", { class: "fixture-fields" },
      el("dt", {}, "Case"), el("dd", {}, episode.case),
      el("dt", {}, "Origin"), el("dd", {}, episode.origin),
      el("dt", {}, "Arm"), el("dd", {}, episode.arm),
      el("dt", {}, "Frozen transfer label"), el("dd", {}, episode.label.transfer ? "yes" : "no"),
      el("dt", {}, "Cell ID"), el("dd", {}, episode.cell_id)),
    el("p", { class: "inspector-note" }, episode.verdict[level()]),
    el("h4", {}, "Observer signals"), el("ul", {}, flags),
    el("h4", {}, "Judge verdicts · pages / pages and access log / answers"), el("ul", {}, judges),
    el("p", {}, "Source cell in the ", el("a", { href: `${REPO}/blob/submission/benchmark/DATACARD.md` }, "submitted benchmark data card"), "."));
}

function renderLandmarkCell(episode, seqs, rowIndex, side) {
  const events = seqs.map((seq) => getStep(episode, seq)).filter(Boolean);
  const list = events.length
    ? el("ol", { class: "landmark-events", "aria-label": `${side} selected source events` }, events.map((step) => eventCard(episode, step, { record: state.record, prefix: `mark-${rowIndex}-${side}`, condensed: true })))
    : el("p", { class: "empty-record" }, "No event was selected for this landmark. Open the complete log to inspect the full sequence.");
  return el("section", { class: "landmark-side", "aria-labelledby": `landmark-${rowIndex}-${side}` },
    el("h4", { id: `landmark-${rowIndex}-${side}` }, `${side === "a" ? "A" : "B"} · Observer record`), list);
}

function renderInstructionsLandmark(left, right) {
  const makeCell = (episode, side) => el("section", { class: "landmark-side instruction-side", "aria-labelledby": `instruction-side-${side}` },
    el("h4", { id: `instruction-side-${side}` }, `${side === "a" ? "A" : "B"} · supplied instructions`),
    state.record === "instr"
      ? instructionsContent(episode, { suffix: `landmark-${side}` })
      : el("p", { class: "empty-record" }, "Not included in the observer record. Select “Complete record, including instructions” below to inspect this source."));
  return el("section", { class: "landmark-group instruction-landmark", "aria-labelledby": "landmark-instructions" },
    el("h3", { id: "landmark-instructions" }, "Instructions"),
    el("p", { class: "landmark-note" }, "A separate source record: the prompts supplied to the agents. It was not shown to the AI judges."),
    el("div", { class: "landmark-pair" }, makeCell(left, "a"), makeCell(right, "b")));
}

function renderCompare() {
  const pair = getPair(state.pair);
  const left = getEpisode(pair.left);
  const right = getEpisode(pair.right);
  const editorial = PAIR_COPY[pair.key];
  setQuestion($("compare-intro"), "compare-title", pair.title);
  $("compare-intro").append(el("p", { class: "comparison-question" }, editorial?.question[level()] || pair.question[level()]));
  $("compare-caption").replaceChildren(
    el("p", {}, "Selected landmarks, not matched turns. Original event numbers remain; full logs follow."));
  const headings = el("div", { class: "comparison-cases", role: "group", "aria-label": "Episodes in this comparison" },
    el("section", {}, el("h3", {}, "Episode A"), el("p", {}, left.model)),
    el("section", {}, el("h3", {}, "Episode B"), el("p", {}, right.model)));
  const rows = (editorial?.landmarks || []).map((landmark, index) => el("section", { class: "landmark-group", "aria-labelledby": `landmark-title-${index}` },
    el("h3", { id: `landmark-title-${index}` }, landmark.title),
    landmark.note ? el("p", { class: "landmark-note" }, landmark.note) : null,
    el("div", { class: "landmark-pair" },
      renderLandmarkCell(left, landmark.left, index, "a"),
      renderLandmarkCell(right, landmark.right, index, "b"))));
  $("landmarks").replaceChildren(headings, ...rows, renderInstructionsLandmark(left, right));
  renderCompareAnswer(pair, left, right);
  $("compare-full").replaceChildren(
    el("p", { class: "record-provenance" }, "Observer records are separate from the experiment fixture. Anonymous shared-board authors stay anonymous in the observer pane; fixture attribution is labelled in the complete record."),
    el("div", { class: "full-compare-grid" }, [left, right].map((episode, index) => el("section", { class: "full-compare-case", "aria-labelledby": `full-case-${index}` },
      el("h3", { id: `full-case-${index}` }, `${index === 0 ? "A" : "B"} · ${episode.title}`),
      sourceDetails(episode, { record: "instr", full: true, prefix: `full-compare-${index}` }),
      instructionsContent(episode, { explanation: true, suffix: `inspector-${index}` }), fullFindings(episode)))));
}

function renderCompareAnswer(pair, left, right) {
  const button = el("button", { type: "button", class: "quiet-action", id: "compare-reveal", "aria-expanded": String(state.revealed), "aria-controls": "compare-answer-result" },
    state.revealed ? "Hide the interpretation" : "Show what the complete records establish");
  const result = el("div", { id: "compare-answer-result", class: "answer-result", hidden: !state.revealed },
    el("h3", {}, "What the complete records establish"),
    el("p", {}, pair.answer[level()]),
    el("div", { class: "answer-pair" }, [left, right].map((episode, index) => el("section", { "aria-labelledby": `answer-${index}` },
      el("h4", { id: `answer-${index}` }, `${index === 0 ? "A" : "B"} · ${episode.kind}`),
      el("p", {}, episode.verdict[level()]),
      el("p", { class: "frozen-label" }, `Frozen transfer label: ${episode.label.transfer ? "yes" : "no"}.`)))));
  $("compare-answer").replaceChildren(button, result);
}

function render() {
  if (!state.data) return;
  const focused = document.activeElement;
  const focusedId = focused?.id;
  const single = state.mode === "single";
  const episode = getEpisode(state.key) || state.data.episodes[0];
  state.key = episode.key;
  $("single").hidden = !single;
  $("compare-view").hidden = single;
  for (const input of document.querySelectorAll('input[name="mode"]')) input.checked = input.value === state.mode;
  for (const input of document.querySelectorAll('input[name="record"]')) input.checked = input.value === state.record;
  picker();
  if (single) renderSingle(episode);
  else renderCompare();
  if (focused && focused !== document.body && focused.isConnected) focused.focus({ preventScroll: true });
  else if (focusedId) document.getElementById(focusedId)?.focus({ preventScroll: true });
}

function picker() {
  const items = state.mode === "single"
    ? state.data.episodes.map((episode) => ({ key: episode.key, title: `${episode.title} · ${episode.model}`, selected: episode.key === state.key }))
    : state.data.compare.map((pair) => ({ key: pair.key, title: pair.title, selected: pair.key === state.pair }));
  const select = el("select", { id: "case-choice", name: "case", "aria-label": state.mode === "single" ? "Episode" : "Comparison" },
    items.map((item) => el("option", { value: item.key, selected: item.selected }, item.title)));
  $("picker").replaceChildren(
    el("label", { for: "case-choice" }, state.mode === "single" ? "Choose an episode" : "Choose a comparison"), select);
}

function setRoute(push = false) {
  const params = new URLSearchParams();
  params.set("record", state.record);
  params.set("step", String(state.step + 1));
  params.set("reveal", state.revealed ? "true" : "false");
  const id = state.mode === "single" ? state.key : state.pair;
  const hash = `#${state.mode}/${encodeURIComponent(id)}?${params.toString()}`;
  const url = `${location.pathname}${location.search}${hash}`;
  if (`${location.pathname}${location.search}${location.hash}` === url) return;
  history[push ? "pushState" : "replaceState"]({ explorer: true }, "", url);
}

function restoreRoute() {
  const fragment = location.hash.slice(1);
  const [path, search = ""] = fragment.split("?", 2);
  const parts = path.split("/").map((part) => {
    try { return decodeURIComponent(part); } catch { return ""; }
  });
  const params = new URLSearchParams(search);
  if (parts[0] === "compare") {
    state.mode = "compare";
    state.pair = getPair(parts[1])?.key || DEFAULT_PAIR;
    state.key = getPair(state.pair).left;
  } else {
    // Both #case and #single/case are preserved for existing links.
    state.mode = "single";
    const key = parts[0] === "single" ? parts[1] : parts[0];
    state.key = getEpisode(key)?.key || state.data.episodes[0].key;
    if (!path) {
      state.mode = "compare";
      state.pair = DEFAULT_PAIR;
      state.key = getPair(DEFAULT_PAIR).left;
    }
  }
  if (!state.pair || !getPair(state.pair)) state.pair = DEFAULT_PAIR;
  if (!RECORDS.includes(params.get("record"))) state.record = "both";
  else state.record = params.get("record");
  state.revealed = params.get("reveal") === "true";
  const activeEpisode = state.mode === "single" ? getEpisode(state.key) : getEpisode(getPair(state.pair).left);
  const requestedStep = Number.parseInt(params.get("step"), 10);
  state.step = Number.isFinite(requestedStep) && requestedStep > 0
    ? Math.min(requestedStep, activeEpisode.steps.length) - 1
    : 0;
  render();
}

function move(step, announce = true, updateUrl = true) {
  const episode = getEpisode(state.key);
  state.step = Math.max(0, Math.min(episode.steps.length - 1, step));
  for (const row of $("timeline").children) {
    const index = [...episode.steps].findIndex((event) => event.seq === Number(row.dataset.seq));
    row.hidden = index > state.step;
    row.classList.toggle("current", index === state.step);
  }
  $("slider").max = episode.steps.length;
  $("slider").value = state.step + 1;
  $("position").textContent = `Event ${state.step + 1} of ${episode.steps.length}`;
  $("prev").disabled = state.step === 0;
  $("next").disabled = state.step === episode.steps.length - 1;
  $("all").disabled = state.step === episode.steps.length - 1;
  if (announce) {
    $("step-status").textContent = `Event ${state.step + 1} of ${episode.steps.length} shown.`;
    $("timeline").children[state.step]?.scrollIntoView({ block: "nearest" });
  }
  if (updateUrl) setRoute(false);
}

function updateRecord(value) {
  state.record = value;
  render();
  setRoute(false);
}

function wire() {
  $("picker").addEventListener("change", (event) => {
    if (state.mode === "single") state.key = getEpisode(event.target.value)?.key || state.key;
    else {
      state.pair = getPair(event.target.value)?.key || state.pair;
      state.key = getEpisode(getPair(state.pair).left).key;
    }
    state.step = 0;
    state.revealed = false;
    setRoute(true);
    render();
  });
  for (const input of document.querySelectorAll('input[name="mode"]')) {
    input.addEventListener("change", () => {
      if (!input.checked) return;
      state.mode = input.value;
      if (state.mode === "compare" && !getPair(state.pair)) state.pair = DEFAULT_PAIR;
      state.step = 0;
      state.revealed = false;
      setRoute(true);
      render();
    });
  }
  for (const input of document.querySelectorAll('input[name="record"]')) {
    input.addEventListener("change", () => input.checked && updateRecord(input.value));
  }
  $("stepper").addEventListener("click", (event) => {
    if (event.target.id === "prev") move(state.step - 1);
    if (event.target.id === "next") move(state.step + 1);
    if (event.target.id === "all") move(Infinity);
  });
  $("slider").addEventListener("input", (event) => move(Number(event.target.value) - 1, false));
  $("app").addEventListener("click", (event) => {
    if (event.target.id === "single-reveal") {
      state.revealed = !state.revealed;
      render();
      setRoute(false);
      $("single-reveal").focus({ preventScroll: true });
    }
    if (event.target.id === "compare-reveal") {
      state.revealed = !state.revealed;
      render();
      setRoute(false);
      $("compare-reveal").focus({ preventScroll: true });
    }
  });
  document.addEventListener("keydown", (event) => {
    if (state.mode !== "single" || event.altKey || event.ctrlKey || event.metaKey) return;
    if (event.target.closest("input, textarea, select, button, summary, [contenteditable]")) return;
    if (event.key === "ArrowRight") move(state.step + 1);
    if (event.key === "ArrowLeft") move(state.step - 1);
  });
  window.addEventListener("popstate", restoreRoute);
  window.addEventListener("hashchange", restoreRoute);
  document.addEventListener("tpa:level", () => render());
}

function fail(error) {
  $("loading").hidden = true;
  const box = $("error");
  box.hidden = false;
  const local = location.protocol === "file:";
  box.replaceChildren(
    local ? "The browser cannot load the episode data from a file URL. "
      : `The episode records did not load${error?.message ? ` (${error.message})` : ""}. Refresh the page to try again. `,
    el("details", {}, el("summary", {}, "Working from a local copy?"),
      el("p", {}, "Serve the docs folder with ", el("code", {}, "python3 -m http.server -d docs"),
        " and open ", el("code", {}, "http://localhost:8000/explorer.html"), ".")),
    " The ", el("a", { href: "./" }, "explainer"), " remains available.");
}

$("loading").hidden = false;
fetch("data/episodes.json")
  .then((response) => {
    if (!response.ok) throw new Error(`HTTP ${response.status}`);
    return response.json();
  })
  .then((data) => {
    state.data = data;
    $("loading").hidden = true;
    $("app").hidden = false;
    document.documentElement.classList.add("explorer-ready");
    wire();
    restoreRoute();
    // A fragmentless visit opens the authored comparison and produces a useful share link.
    if (!location.hash) setRoute(false);
  })
  .catch(fail);
